inp = [[0]*20 for _ in range(20)]
dots = [(1,5),(2,6),(4,5),(7,1),(3,19),(8,19),(12,9),(17,13),(19,15)]
for r,c in dots: inp[r][c]=1
for r in range(2,9):
    for c in range(9,16): inp[r][c]=2
br=(2,8); bc=(9,15)
out=[row[:] for row in inp]
rowdots={r:c for r,c in dots if br[0]<=r<=br[1]}
coldots={c:r for r,c in dots if bc[0]<=c<=bc[1]}
W=H=20
for r in range(br[0],br[1]+1):
    if r in rowdots:
        c=rowdots[r]
        if c>bc[1]:  # dot right -> fill left
            for cc in range(0,bc[0]): out[r][cc]=2
        else:        # dot left -> fill right
            for cc in range(bc[1]+1,W): out[r][cc]=2
    else:
        out[r]=[2]*W
for c in range(bc[0],bc[1]+1):
    if c in coldots:
        rr=coldots[c]
        if rr>br[1]:
            for r in range(0,br[0]): out[r][c]=2
        else:
            for r in range(br[1]+1,H): out[r][c]=2
    else:
        for r in range(H): out[r][c]=2
for row in out: print(' '.join(map(str,row)))

